/* Operands of xck_gga_st_o2_m_mo_t: `fields` in the order of
 * xck_gga_st_o2_m_mo_field_names, `xc` in the order of xck_gga_st_o2_m_mo_xc_names (the
 * C ABI's `scal` is the two concatenated, split at n_fields). The
 * structs name them; the overload taking them packs the arrays. */
inline constexpr int xck_gga_st_o2_m_mo_n_fields = 4;
inline constexpr int xck_gga_st_o2_m_mo_n_xc = 13;
inline constexpr const char* xck_gga_st_o2_m_mo_field_names[] = {"w", "rho_a_x", "rho_a_y", "rho_a_z"};
inline constexpr const char* xck_gga_st_o2_m_mo_xc_names[] = {"vsigma_0", "vsigma_1", "v2rho2_0", "v2rho2_1", "v2rhosigma_0", "v2rhosigma_1", "v2rhosigma_2", "v2rhosigma_3", "v2rhosigma_4", "v2sigma2_0", "v2sigma2_1", "v2sigma2_2", "v2sigma2_4"};
template <typename T>
struct xck_gga_st_o2_m_mo_fields {
    const T* w;
    const T* rho_a_x;
    const T* rho_a_y;
    const T* rho_a_z;
};
template <typename Txc>
struct xck_gga_st_o2_m_mo_xc {
    const Txc* vsigma_0;
    const Txc* vsigma_1;
    const Txc* v2rho2_0;
    const Txc* v2rho2_1;
    const Txc* v2rhosigma_0;
    const Txc* v2rhosigma_1;
    const Txc* v2rhosigma_2;
    const Txc* v2rhosigma_3;
    const Txc* v2rhosigma_4;
    const Txc* v2sigma2_0;
    const Txc* v2sigma2_1;
    const Txc* v2sigma2_2;
    const Txc* v2sigma2_4;
};

template <typename T, typename Txc = T>
int xck_gga_st_o2_m_mo_t(int64_t npts,
        int64_t nocc,
        int64_t nvir,
        int64_t nx,
        const T* phi_o,
        const T* phi_v,
        const double* X,
        const xck_gga_st_o2_m_mo_fields<T>& fields_,
        const xck_gga_st_o2_m_mo_xc<Txc>& xc_,
        T* out,
        T* work = nullptr) {
    const T* f_[] = {fields_.w, fields_.rho_a_x, fields_.rho_a_y, fields_.rho_a_z};
    const Txc* x_[] = {xc_.vsigma_0, xc_.vsigma_1, xc_.v2rho2_0, xc_.v2rho2_1, xc_.v2rhosigma_0, xc_.v2rhosigma_1, xc_.v2rhosigma_2, xc_.v2rhosigma_3, xc_.v2rhosigma_4, xc_.v2sigma2_0, xc_.v2sigma2_1, xc_.v2sigma2_2, xc_.v2sigma2_4};
    return xck_gga_st_o2_m_mo_t<T, Txc>(npts, nocc, nvir, nx, phi_o, phi_v, X, f_, x_, out, work);
}

